#include <iostream>
#include <cstring>
#include "join.h"
#include "file.h"
#include "blkio.h"
#include "mergeSort.h"

using namespace std;

int sortMergeJoin(Buffer *buf)
{
	/* ---- stage 1: sort_merge_preparation ---- */

	/* Sort R and S with the external merge sort.
	 * Sorted R is chained from MERGE_R_RET_ADDR (16 blocks),
	 * sorted S from MERGE_S_RET_ADDR (32 blocks). */
	mergeSort(buf, SORT_R);
	mergeSort(buf, SORT_S);

	/* Reset the result writer stream for the join output. */
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, true);

	/* Load the first block of each sorted relation and hold both slots. */
	unsigned char *rBlk = readBlockFromDisk(MERGE_R_RET_ADDR, buf);
	unsigned char *sBlk = readBlockFromDisk(MERGE_S_RET_ADDR, buf);

	Relation rT[TUPLE_PER_BLK];
	Relation sT[TUPLE_PER_BLK];
	readTuplesFromBlock(rBlk, rT);
	readTuplesFromBlock(sBlk, sT);

	int rPos = 0;
	int sPos = 0;
	bool rEnd = (rBlk == NULL);
	bool sEnd = (sBlk == NULL);

	/* Duplicate-key groups collected during the merge scan. */
	Relation rg[R_NUM];
	Relation sg[S_NUM];

	/* ---- stage 2: sort_merge_join ---- */

	/* Advance a cursor: move to the next tuple; at a block boundary read
	 * the chain next-pointer at offset 60, release the held block slot,
	 * then load and decode the next block (or mark the side exhausted). */
	auto advance = [&](unsigned char *&blk, Relation *T, int &pos, bool &end) {
		pos++;
		if (pos >= TUPLE_PER_BLK) {
			unsigned int next = 0;
			memcpy(&next, blk + BLK_SIZE - PTR_SIZE, PTR_SIZE);
			freeBlockInBuffer(blk, buf);
			blk = NULL;
			if (next != 0) {
				blk = readBlockFromDisk(next, buf);
				readTuplesFromBlock(blk, T);
				pos = 0;
			} else {
				end = true;
			}
		}
	};

	/* Classic two-pointer merge with duplicate-key groups.
	 * At most one R block and one S block slot are held at any time. */
	while (!rEnd && !sEnd) {
		if (rT[rPos].attr1 < sT[sPos].attr1) {
			advance(rBlk, rT, rPos, rEnd);
			continue;
		}
		if (rT[rPos].attr1 > sT[sPos].attr1) {
			advance(sBlk, sT, sPos, sEnd);
			continue;
		}
		int k = rT[rPos].attr1;
		int rn = 0;
		int sn = 0;
		while (!rEnd && rT[rPos].attr1 == k) {
			rg[rn++] = rT[rPos];
			advance(rBlk, rT, rPos, rEnd);
		}
		while (!sEnd && sT[sPos].attr1 == k) {
			sg[sn++] = sT[sPos];
			advance(sBlk, sT, sPos, sEnd);
		}
		for (int i = 0; i < rn; i++)
			for (int j = 0; j < sn; j++)
				output(buf, SMJ_RET_ADDR, k, rg[i].attr2, sg[j].attr2);
	}

	/* Free any still-held blocks, then flush the partial tail block. */
	if (rBlk != NULL)
		freeBlockInBuffer(rBlk, buf);
	if (sBlk != NULL)
		freeBlockInBuffer(sBlk, buf);
	pushToWrite(buf, NULL, 0, SMJ_RET_ADDR, false, true);
	return 0;
}
